const ICON_LEAD = {"Owner:": "briefcase", "Store manager:": "shop", "Cashier:": "receipt", "Finance:": "calculator", "Access admin:": "shield-user", "No PM or spec": "help-circle", "Separate identities": "layers", "Online has no stores": "arrow-swap-horizontal", "[To fill: no task": "graph", "In-store payments:": "shop", "Online payments:": "globe", "Cards, cross-border": "card", "Gifting & card issuing:": "card", "API infrastructure:": "code", "A new login": "shield-user", "One Pine Labs:": "grid", "One business picture:": "chart-bar-trend-up", "Money has stages:": "arrow-right-circle", "Answers where I look:": "search-normal", "Products to discover:": "magic-star", "I see what I can act on:": "shield-user", "Regulation keeps": "layers", "Online and in-store each": "shield-user", "Merge identity": "user", "Up to about 70%": "headphones", "Bank account problems": "card", "The online portal had no": "help-circle", "Pine Labs ONE had no": "receipt", "Stripe, Adyen": "globe", "Razorpay, PhonePe": "shop", "With one platform, a merchant": "clipboard-text", "Totals added up": "calculator", "In-store merchants never": "link", "Product managers:": "clipboard-text", "Online & in-store tech:": "code", "Support: ticket": "headphones", "Business: adoption": "chart-bar-trend-up", "One brand green:": "palette", "Status only:": "info-circle", "Calm by default:": "bell-off", "Before:": "close-circle", "Now:": "tick-circle", "Numbers:": "hashtag", "[To fill: what you'd repeat": "tick-circle", "[To fill: e.g. bring": "refresh", "[To fill: next phase": "arrow-right-circle"};
const ICON_LABEL = {"ROLE": "user", "STAKEHOLDERS": "people", "SCOPE": "layers", "RESEARCH": "search-normal", "DOMAIN": "briefcase", "HANDOFF": "code", "BUSINESS GOAL": "chart-bar-trend-up", "MERCHANT GOAL": "shop", "TECH GOAL": "code", "CASE STUDY \u00b7 B2B2C \u00b7 LEAD DESIGNER": "pen-tool", "CASE STUDY \u00b7 B2B FINTECH \u00b7 LEAD DESIGNER": "grid", "EXPERIMENTS \u00b7 AI": "magic-star"};
const PAGE_ID = "538:3798";
const TITLE_FAMILIES = ["EB Garamond", "Platypi", "Timeless Serif"];
const BODY_SECTIONS = /^(Pine One — Case study|Portfolio — Index|Experiments — Designing with AI)/;

async function pickStyle(family, wanted) {
  const fonts = await figma.listAvailableFontsAsync();
  const styles = fonts.filter((f) => f.fontName.family === family).map((f) => f.fontName.style);
  for (const s of wanted) if (styles.includes(s)) return { family, style: s };
  return null;
}

function insideDiagram(node) {
  for (let p = node.parent; p && p.type !== "PAGE"; p = p.parent) if (/^(Wireframe|Diagram) \//.test(p.name)) return true;
  return false;
}
function inBodySection(node) {
  for (let p = node.parent; p && p.type !== "PAGE"; p = p.parent) if (/^Tour tooltip/.test(p.name)) return true;
  for (let p = node.parent; p && p.type !== "PAGE"; p = p.parent) if (p.type === "SECTION") return BODY_SECTIONS.test(p.name);
  return false;
}

async function swap(textNodes, mapFont) {
  let changed = 0;
  for (const t of textNodes) {
    const segs = t.getStyledTextSegments(["fontName"]);
    const plan = segs.map((s) => ({ s, to: mapFont(s.fontName, t) })).filter((x) => x.to);
    if (!plan.length) continue;
    for (const { s, to } of plan) { await figma.loadFontAsync(s.fontName); await figma.loadFontAsync(to); }
    for (const { s, to } of plan) t.setRangeFontName(s.start, s.end, to);
    changed++;
  }
  return changed;
}


// "icons": Reicon outline icons (MIT, github.com/dqev/reicon) on category cards, card labels and Before/Now cards.
function iconNode(name, color) {
  const svg = `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">${REICON[name].replace(/currentColor/g, color)}</svg>`;
  const n = figma.createNodeFromSvg(svg); n.name = `Icon / ${name}`; n.resize(24, 24); return n;
}
const hasIcon = (f) => f.children.some((c) => c.name && c.name.startsWith("Icon / "));
async function addIcons(page) {
  const secs = page.children.filter((n) => n.type === "SECTION" && BODY_SECTIONS.test(n.name));
  let added = 0;
  for (const sec of secs) {
    // Cards matched by their lead text: the icon replaces the 01/02 number, or leads the card.
    for (const card of sec.findAll((n) => n.type === "FRAME" && n.name === "Card")) {
      if (hasIcon(card)) continue;
      const texts = card.findAll((n) => n.type === "TEXT");
      const main = texts[texts.length - 1]; if (!main) continue;
      const lead = Object.keys(ICON_LEAD).find((k) => main.characters.startsWith(k));
      if (!lead) continue;
      const name = ICON_LEAD[lead];
      const color = lead === "Now:" ? "#0F9B74" : lead === "Before:" ? "#8C9490" : "#5C6461";
      const num = card.children.find((c) => c.type === "TEXT" && /^\s*\d{2}\s*$/.test(c.characters));
      const ic = iconNode(name, color);
      if (num) { const i = card.children.indexOf(num); num.remove(); card.insertChild(i, ic); }
      else card.insertChild(0, ic);
      added++;
    }
    // Labelled cards (cover facts, goals, index): icon above the label.
    for (const t of sec.findAll((n) => n.type === "TEXT")) {
      const key = ICON_LABEL[t.characters.trim().toUpperCase()];
      if (!key) continue;
      const parent = t.parent;
      if (!parent || parent.layoutMode !== "VERTICAL" || hasIcon(parent)) continue;
      parent.insertChild(parent.children.indexOf(t), iconNode(key, "#5C6461"));
      added++;
    }
  }
  // Keep the cover's fact grid bottom-aligned after it grows.
  for (const sec of secs) for (const s of sec.children) {
    const grid = s.type === "FRAME" && s.children.find((c) => c.name === "Meta");
    if (grid) grid.y = 1080 - 96 - grid.height;
  }
  return added;
}

// Narrow card text so it fits beside a newly added icon.
function fitCards(page) {
  let fixed = 0;
  const secs = page.children.filter((n) => n.type === "SECTION" && BODY_SECTIONS.test(n.name));
  for (const sec of secs) for (const card of sec.findAll((n) => n.type === "FRAME" && n.name === "Card" && n.layoutMode === "HORIZONTAL")) {
    const icon = card.children.find((c) => c.name && c.name.startsWith("Icon / "));
    if (!icon) continue;
    const others = card.children.filter((c) => c !== icon);
    const body = others[others.length - 1];
    const fixedW = others.slice(0, -1).reduce((a, c) => a + c.width, 0);
    const avail = card.width - card.paddingLeft - card.paddingRight - card.itemSpacing * (card.children.length - 1) - icon.width - fixedW;
    if (body.width <= avail + 0.5) continue;
    if (body.type === "TEXT") { body.resize(avail, body.height); body.textAutoResize = "HEIGHT"; }
    else { body.resize(avail, body.height); if ("primaryAxisSizingMode" in body && body.layoutMode === "VERTICAL") body.primaryAxisSizingMode = "AUTO"; for (const t of body.findAll((n) => n.type === "TEXT")) { t.resize(Math.min(t.width, avail), t.height); t.textAutoResize = "HEIGHT"; } }
    fixed++;
  }
  return fixed;
}

