  const INK = { r: 23 / 255, g: 23 / 255, b: 23 / 255 }, MUTED = { r: 115 / 255, g: 115 / 255, b: 115 / 255 }, LINE = { r: 212 / 255, g: 212 / 255, b: 212 / 255 }, WHITE = { r: 1, g: 1, b: 1 };
