  const plain = (f) => { f.fills = []; f.cornerRadius = 0; f.strokes = []; };
  const eyebrow = (t) => { t.fontName = gsm; t.fontSize = 16; t.textCase = "UPPER"; t.lineHeight = { unit: "PERCENT", value: 110 }; t.fills = [{ type: "SOLID", color: MUTED }]; };
