      const isStat = (S) => S.type === "FRAME" && S.layoutMode === "VERTICAL" && S.name !== "Card" && S.name !== "Row" && S.strokes.length && S.children.length === 2 && S.children.every((c) => c.type === "TEXT" && c.fontName !== figma.mixed && /General Sans|Inter/.test(c.fontName.family) && c.fontSize >= 16);
      const stats = F.findAll(isStat);
