      if (!card || card.getPluginData("issues") === "1") { log.done.push(ids[k] + " skip"); continue; }
      const rows = card.children.filter((r) => r.name === "Row");
      // the k-th section is the k-th row (earlier slides only hold their own sections)
      const row = rows[Math.min(k, rows.length - 1)];
      const texts = row.findAll((n) => n.type === "TEXT");
      const body = texts[texts.length - 1];
      const lines = body.characters.split(/\n+/).map((l) => l.trim()).filter(Boolean);
