async function navFix(set) {
  for (const c of set.children) { c.layoutGrow = 0; c.layoutSizingHorizontal = "FIXED"; c.layoutSizingVertical = "FIXED"; c.resize(69, 64); }
  set.clipsContent = false; set.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }]; set.layoutWrap = "WRAP"; set.primaryAxisSizingMode = "FIXED"; set.resize(2 * 69 + 16 + 48 + 4, Math.max(set.height, 100)); set.counterAxisSizingMode = "AUTO";
  return { set: set.id, fixed: set.children.length };
}
async function navComponent() {
  const existing = figma.currentPage.findOne((n) => n.type === "COMPONENT_SET" && n.name === "Bottom nav item");
  if (existing) return navFix(existing);
  const bar = await figma.getNodeByIdAsync("7067:111478");
  if (!bar) throw new Error("Open the PineOne Omni-channel file (bar 7067:111478) first.");
  let pg = bar; while (pg.type !== "PAGE") pg = pg.parent; await figma.setCurrentPageAsync(pg);
  const items = bar.findAll((n) => n.type === "FRAME" && /^Nav item/.test(n.name));
  const sel = items.find((n) => n.findOne((x) => /\(Filled\)/.test(x.name)));
  const def = items.find((n) => n !== sel && n.findOne((x) => x.name === "State layer" && Math.round(x.width) === 32));
  const label = (n) => n.findOne((x) => x.type === "TEXT");
  for (const n of [sel, def]) { const t = label(n); for (const g of t.getStyledTextSegments(["fontName"])) await figma.loadFontAsync(g.fontName); }
  const iconColor = (n) => { const v = n.findOne((x) => x.name === "State layer").findOne((x) => (x.type === "VECTOR" || x.type === "BOOLEAN_OPERATION") && x.fills && x.fills !== figma.mixed && x.fills.length); return v ? v.fills[0].color : { r: 0, g: 0, b: 0 }; };
  const hex = (c) => "#" + [c.r, c.g, c.b].map((v) => Math.round(v * 255).toString(16).padStart(2, "0")).join("");
  const LIST = [["Overview", "home"], ["Payments", "wallet-money"], ["Settlement", "bank"], ["Support", "chat-line"], ["More", "arrow-up2"]];
  const comps = [];
  for (const [name, icon] of LIST) for (const state of ["Default", "Selected"]) {
    const srcItem = state === "Selected" ? sel : def;
    const c = srcItem.clone(); figma.currentPage.appendChild(c);
    const comp = figma.createComponentFromNode(c);
    comp.name = `Item=${name}, State=${state}`;
    const t = label(comp); t.characters = name;
    const layer = comp.findOne((x) => x.name === "State layer");
    const old = layer.children[0];
    const weight = state === "Selected" && NAV_ICONS[icon].Filled ? "Filled" : "Outline";
    const svg = `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">${NAV_ICONS[icon][weight].replace(/currentColor/g, hex(iconColor(srcItem)))}</svg>`;
    const ic = figma.createNodeFromSvg(svg); ic.name = `Reicon / ${icon} (${weight})`;
    const idx = layer.children.indexOf(old); layer.insertChild(idx, ic);
    if (layer.layoutMode === "NONE" || !layer.layoutMode) { ic.x = old.x; ic.y = old.y; }
    old.remove();
    comps.push(comp);
  }
  const set = figma.combineAsVariants(comps, figma.currentPage);
  set.name = "Bottom nav item";
  set.layoutMode = "HORIZONTAL"; set.layoutWrap = "WRAP"; set.itemSpacing = 16; set.counterAxisSpacing = 16;
  set.paddingTop = set.paddingBottom = set.paddingLeft = set.paddingRight = 24;
  set.resize(2 * 69 + 16 + 48, 100); set.primaryAxisSizingMode = "FIXED"; set.counterAxisSizingMode = "AUTO";
  set.cornerRadius = 8; set.strokes = [{ type: "SOLID", color: { r: 0.6, g: 0.4, b: 1 } }]; set.dashPattern = [6, 4]; set.strokeWeight = 1;
  const top = (() => { let a = bar; while (a.parent.type !== "PAGE") a = a.parent; return a; })();
  set.x = top.x + top.width + 200; set.y = top.y;
  await navFix(set);
  figma.currentPage.selection = [set]; figma.viewport.scrollAndZoomIntoView([set]);
  return { set: set.id, variants: comps.length };
}

// "navbar": full bottom nav component, one variant per selected tab, built from Bottom nav item instances.
async function navBarComponent() {
  const items = figma.currentPage.findOne((n) => n.type === "COMPONENT_SET" && n.name === "Bottom nav item");
  if (!items) throw new Error("Run 'Bottom nav → component' first.");
  const existing = figma.currentPage.findOne((n) => n.type === "COMPONENT_SET" && n.name === "Bottom nav");
  if (existing) existing.remove();
  const bar = await figma.getNodeByIdAsync("7067:111478");
  const NAMES = ["Overview", "Payments", "Settlement", "Support", "More"];
  const variant = (name, state) => items.children.find((c) => c.name === `Item=${name}, State=${state}`);
  const comps = [];
  for (const sel of NAMES) {
    const c = bar.clone(); figma.currentPage.appendChild(c);
    const nav = c.findOne((n) => n.name === "Navigation Bar: Vertical items");
    const olds = nav.children.filter((n) => /^Nav item/.test(n.name));
    NAMES.forEach((name, i) => {
      const old = olds[i]; const inst = variant(name, name === sel ? "Selected" : "Default").createInstance();
      nav.insertChild(nav.children.indexOf(old), inst);
      if (nav.layoutMode && nav.layoutMode !== "NONE") { inst.layoutSizingHorizontal = "FILL"; inst.layoutSizingVertical = "FIXED"; } else { inst.x = old.x; inst.y = old.y; inst.resize(old.width, old.height); }
      inst.name = name; old.remove();
    });
    const comp = figma.createComponentFromNode(c); comp.name = `Selected=${sel}`; comps.push(comp);
  }
  const set = figma.combineAsVariants(comps, figma.currentPage); set.name = "Bottom nav";
  set.layoutMode = "VERTICAL"; set.itemSpacing = 24; set.paddingTop = set.paddingBottom = set.paddingLeft = set.paddingRight = 24;
  set.primaryAxisSizingMode = "AUTO"; set.counterAxisSizingMode = "AUTO"; set.clipsContent = false;
  set.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }]; set.cornerRadius = 8;
  set.strokes = [{ type: "SOLID", color: { r: 0.6, g: 0.4, b: 1 } }]; set.dashPattern = [6, 4]; set.strokeWeight = 1;
  set.x = items.x + items.width + 120; set.y = items.y;
  figma.currentPage.selection = [set]; figma.viewport.scrollAndZoomIntoView([set]);
  return { set: set.id, variants: comps.length };
}

